const assert=require('node:assert/strict'),{spawnSync}=require('node:child_process'),{writeFileSync}=require('node:fs');
const safeFailure='AI record cleanup failed. Check database configuration, coordinator, and availability.';
const results=[];
for(const [name,value,expected] of [['isolated-success',process.env.TEST_DATABASE_URL,0],['empty','',1],['invalid','https://synthetic-user:synthetic-sensitive@invalid.invalid/not-postgres',1]]){
 const r=spawnSync(process.execPath,['src/server/dist/ai/cleanup-ai-records.js'],{encoding:'utf8',timeout:30000,env:{...process.env,DATABASE_URL:value,AI_LIVE_ENABLED:'false'}});
 assert.ok(r.status===expected,'Unexpected retention CLI exit status');
 const output=(r.stdout||'')+(r.stderr||'');
 assert.ok(output.trim()===(expected===0?'AI record cleanup completed.':safeFailure),'Retention CLI output must be the fixed safe message');
 assert.ok(!output.includes('synthetic-sensitive')&&!output.includes('synthetic-user')&&!output.includes(value||'not-present'),'Retention CLI disclosed sensitive configuration');
 results.push({caseId:name,exitCode:r.status,safeMessage:true});
}
